# def -- define a reusable block of code
def get_payment_tier(amount):
    if amount >= 500:   return "Premium"
    if amount >= 200:   return "Standard"
    if amount >= 50:    return "Basic"
    return "Low"

print(get_payment_tier(350))   # Standard
print(get_payment_tier(600))   # Premium

# Multiple return values
def validate_order(order):
    if not order.get("order_id"):
        return False, "Missing order_id"
    if order.get("payment_value", 0) <= 0:
        return False, "Invalid payment"
    return True, "OK"

ok, msg = validate_order({
    "order_id": "abc",
    "payment_value": 137.09
})
print(ok, msg)  # True OK

# Sets for deduplication -- O(1) lookup
raw_order_ids = [
    "e481f51c", "a1b2c3d4",
    "e481f51c",  # duplicate!
    "f9c3e456", "a1b2c3d4",  # duplicate!
]

seen   = set()
unique = []
dupes  = 0

for oid in raw_order_ids:
    if oid in seen:
        dupes += 1
        continue
    seen.add(oid)
    unique.append(oid)

print(f"Unique: {len(unique)}, Dupes removed: {dupes}")
# Unique: 3, Dupes removed: 2

# Set operations
set_a = {"SP", "RJ", "MG"}
set_b = {"RJ", "RS", "PR"}
print(set_a & set_b)   # Intersection: {'RJ'}
print(set_a | set_b)   # Union: all states
print(set_a - set_b)   # Difference: {'SP', 'MG'}

# Retry logic -- handle rate limits and timeouts
import requests, time

def safe_get(url, headers=None, retries=3):
    for attempt in range(1, retries + 1):
        try:
            resp = requests.get(url, headers=headers, timeout=10)
            resp.raise_for_status()
            return resp.json()

        except requests.exceptions.Timeout:
            print(f"Timeout on attempt {attempt}")

        except requests.exceptions.HTTPError as e:
            if e.response.status_code == 429:
                wait = int(e.response.headers.get("Retry-After", 5))
                print(f"Rate limited -- waiting {wait}s")
                time.sleep(wait)
            elif e.response.status_code in (400, 401, 403, 404):
                raise   # don't retry client errors

        if attempt < retries:
            time.sleep(2 ** attempt)  # 2s, 4s, 8s

    return None

