import logging

logger = logging.getLogger("pipeline")

def process_with_threshold(records, max_rate=0.05):
    valid, errors = [], []

    for rec in records:
        try:
            if not rec.get("order_id"):
                raise ValueError("Missing order_id")
            valid.append(rec)
        except Exception as e:
            errors.append(rec)
            logger.warning(f"Error: {e}")

    rate = len(errors) / len(records)
    if rate > max_rate:
        logger.error(f"Error rate {rate:.1%} — HALT")
        raise RuntimeError("Too many errors")
    return valid, errors
